webpackJsonp([0x7d1d4f78ccaf],{444:function(s,a){s.exports={data:{site:{siteMetadata:{title:"Mihail Eric",subtitle:"Engineer, researcher, educator.",copyright:"Copyright",author:{name:"Mihail Eric",twitter:"mihail_eric"},url:"https://mihaileric.com"}},allMarkdownRemark:{edges:[{node:{fields:{slug:"/posts/model-evaluation/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Model Evaluation",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/principal-components-analysis/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Principal Components Analysis",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/feature-selection/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"What Features Do You Want?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/regularization/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Model Regularization",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/bias-variance-tradeoff/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Controlling Your Model's Bias",tags:["Machine Learning","A.I.","Data Science"],date:"2019-08-25T23:46:37.121"}}},{node:{fields:{slug:"/posts/nlp-trends-acl-2019/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Trends in Natural Language Processing: ACL 2019 In Review",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2019-08-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/what-kmeans-clustering/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"What K-Means",tags:["Machine Learning","A.I.","Data Science"],date:"2019-07-16T23:46:37.121"}}},{node:{fields:{slug:"/posts/recurrent-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Recurrent Neural Networks",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:46:37.121"}}},{node:{fields:{slug:"/posts/convolutional-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Dance Dance Convolution",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T23:40:37.121"}}},{node:{fields:{slug:"/posts/neural-network-grab-bag/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Neural Network Grab Bag",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-05-03T22:46:37.121"}}},{node:{fields:{slug:"/posts/deep-dive-into-neural-networks/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Deep Dive Into Neural Networks",tags:["Machine Learning","A.I.","Deep Learning"],date:"2019-04-28T23:46:37.121"}}},{node:{fields:{slug:"/posts/support-vector-machines/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Basics of Support Vector Machines",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-20T23:46:37.121"}}},{node:{fields:{slug:"/posts/not-so-naive-bayes/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Why So Naive, Bayes?",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-13T23:46:37.121"}}},{node:{fields:{slug:"/posts/introduction-to-logistic-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Introduction to Logistic Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-04-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamentals-of-linear-regression/",tagSlugs:["/tags/machine-learning/","/tags/a-i/","/tags/data-science/"]},frontmatter:{title:"Fundamentals of Linear Regression",tags:["Machine Learning","A.I.","Data Science"],date:"2019-03-15T23:46:37.121"}}},{node:{fields:{slug:"/posts/transformers-attention-in-disguise/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Transformers: Attention in Disguise",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-22T23:46:37.121"}}},{node:{fields:{slug:"/posts/deep-contextualized-word-representations-elmo/",tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Deep Contextualized Word Representations with ELMo",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-08T23:46:37.121"}}},{node:{fields:{slug:"/posts/fast-object-detection-with-fast-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Fast Object Detection with Fast R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/object-detection-with-rcnn/",tagSlugs:["/tags/machine-learning/","/tags/computer-vision/","/tags/deep-learning/"]},frontmatter:{title:"Object Detection with R-CNN",tags:["Machine Learning","Computer Vision","Deep Learning"],date:"2018-10-01T23:46:37.121"}}},{node:{fields:{slug:"/posts/fundamental-deep-learning-algorithms-to-learn/",tagSlugs:["/tags/a-i/","/tags/deep-learning/","/tags/machine-learning/"]},frontmatter:{title:"Fundamental Deep Learning Algorithms To Learn",tags:["A.I.","Deep Learning","Machine Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/why-all-the-excitement-about-ai/",tagSlugs:["/tags/a-i/","/tags/machine-learning/","/tags/deep-learning/"]},frontmatter:{title:"Why All The Excitement About Artificial Intelligence",tags:["A.I.","Machine Learning","Deep Learning"],date:"2018-08-14T23:46:37.121"}}},{node:{fields:{slug:"/posts/being-a-good-machine-learning-data-scientist/",tagSlugs:["/tags/a-i/","/tags/data-science/","/tags/machine-learning/"]},frontmatter:{title:"Being a Good Machine Learning Engineer/Data Scientist",tags:["A.I.","Data Science","Machine Learning"],date:"2018-08-11T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-software-interview-challenge/",tagSlugs:["/tags/software-engineering/","/tags/interview-prep/"]},frontmatter:{title:"A Software Interview Challenge",tags:["Software Engineering","Interview Prep"],date:"2017-12-24T23:46:37.121"}}},{node:{fields:{slug:"/posts/review-of-sigdial-semdial-2017/",tagSlugs:["/tags/natural-language-processing/","/tags/a-i/","/tags/deep-learning/"]},frontmatter:{title:"Review of SIGDial/SemDial 2017",tags:["Natural Language Processing","A.I.","Deep Learning"],date:"2017-09-04T23:46:37.121"}}},{node:{fields:{slug:"/posts/a-new-multiturn-dialogue-dataset/",tagSlugs:["/tags/natural-language-processing/","/tags/dataset/","/tags/dialogue/"]},frontmatter:{title:"A New Multi-Turn, Multi-Domain, Task-Oriented Dialogue Dataset",tags:["Natural Language Processing","Dataset","Dialogue"],date:"2017-07-03T23:46:37.121"}}}]},markdownRemark:{id:"/Users/mihaileric/Documents/Projects/mihail911.github.io/src/pages/articles/2018-22-10---Transformers-Attention-In-Disguise/index.md absPath of file >>> MarkdownRemark",html:'<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/transformers-bumblebee-d4ec62a6a46aae8f83b7419242f59f4e-48854.jpg"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 56.18556701030928%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/jpeg;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Transformers bumblebee shot"\n        title=""\n        src="/static/transformers-bumblebee-d4ec62a6a46aae8f83b7419242f59f4e-c6823.jpg"\n        srcset="/static/transformers-bumblebee-d4ec62a6a46aae8f83b7419242f59f4e-dad4f.jpg 240w,\n/static/transformers-bumblebee-d4ec62a6a46aae8f83b7419242f59f4e-1808a.jpg 480w,\n/static/transformers-bumblebee-d4ec62a6a46aae8f83b7419242f59f4e-c6823.jpg 960w,\n/static/transformers-bumblebee-d4ec62a6a46aae8f83b7419242f59f4e-48854.jpg 970w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>In this post, we will be describing a class of sequence processing models known as Transformers (…<em>robots in disguise</em>).\nJokes aside, Transformers came out on the scene not too long ago and have rocked the natural language processing community because of\ntheir pitch: state-of-the-art and efficient sequence processing <strong>without recurrent units or convolution</strong>. </p>\n<p><em>“No recurrent units or convolution?! What are these models even made of?!”</em>, you may be exclaiming to unsuspecting strangers on the streets. </p>\n<p>Not much it turns out, other than a bunch of attention and feedforward operations. </p>\n<p>While the individual components that make up the Transformer model are not particularly novel, this is still a pretty dense paper with a lot\nof moving parts. So our aim in this post will be to distill the model to its key contributions, without getting too stuck\nin the details.</p>\n<p>But first, the TLDR for the paper:</p>\n<ol>\n<li><strong>Transformers demonstrate that recurrence and convolution are not essential for building high-performance natural language models</strong></li>\n<li><strong>They achieve state-of-the-art machine translation results using a self-attention operation</strong></li>\n<li><strong>Attention is a highly-efficient operation due to its parallelizability and runtime characteristics</strong></li>\n</ol>\n<p>If that sounds exciting, read onward!</p>\n<h2>How Transformers Work</h2>\n<p>While the Transformer does not use traditional recurrent units or convolutions, it still takes inspiration from\nsequence-to-sequence architectures where we encode some input and iteratively decode a desired output. </p>\n<p>How does this play out in practice? Let’s focus on the encoder first. There are quite a few elements to the process,\nso don’t get too lost in the details. All we are doing is encoding some inputs 🙂.</p>\n<p>Assume we start with a certain phrase that we would like to translate from Spanish to English. The Transformer\nbegins by embedding the tokens of the Spanish phrase into a conventional embedding matrix:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/input_embedding_matrix-a2e9df88621a1dae9c4c16b097b808ae-1c473.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 25.585023400936034%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Input embedding matrix of transformer model"\n        title=""\n        src="/static/input_embedding_matrix-a2e9df88621a1dae9c4c16b097b808ae-3d61e.png"\n        srcset="/static/input_embedding_matrix-a2e9df88621a1dae9c4c16b097b808ae-d182c.png 240w,\n/static/input_embedding_matrix-a2e9df88621a1dae9c4c16b097b808ae-5220f.png 480w,\n/static/input_embedding_matrix-a2e9df88621a1dae9c4c16b097b808ae-3d61e.png 960w,\n/static/input_embedding_matrix-a2e9df88621a1dae9c4c16b097b808ae-1c473.png 1282w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Because the model makes no use of recurrence, we need some way to represent position-based information\nin the model. Hence we add a positional encoding to this embedding matrix, whose exact form we will describe\nin the next section:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/positional_encoding_added-9eb9de50b7ddfe4287ef9e386649e292-d8e49.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 39.586919104991395%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Positional encoding added to embedding matrix in Transformer model"\n        title=""\n        src="/static/positional_encoding_added-9eb9de50b7ddfe4287ef9e386649e292-3d61e.png"\n        srcset="/static/positional_encoding_added-9eb9de50b7ddfe4287ef9e386649e292-d182c.png 240w,\n/static/positional_encoding_added-9eb9de50b7ddfe4287ef9e386649e292-5220f.png 480w,\n/static/positional_encoding_added-9eb9de50b7ddfe4287ef9e386649e292-3d61e.png 960w,\n/static/positional_encoding_added-9eb9de50b7ddfe4287ef9e386649e292-d8e49.png 1162w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Our modified input is fed into the first layer of the Transformer encoder. Within each encoder layer,\nwe perform a series of operations on the inputs.</p>\n<p>First off, we feed the input through a multi-head attention operation:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/multihead_attention_encoder-503fd3d322872609873e62cbb1ca98d4-71c2a.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 50.263620386643225%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Multi-head attention operation in encoder of Transformer model"\n        title=""\n        src="/static/multihead_attention_encoder-503fd3d322872609873e62cbb1ca98d4-3d61e.png"\n        srcset="/static/multihead_attention_encoder-503fd3d322872609873e62cbb1ca98d4-d182c.png 240w,\n/static/multihead_attention_encoder-503fd3d322872609873e62cbb1ca98d4-5220f.png 480w,\n/static/multihead_attention_encoder-503fd3d322872609873e62cbb1ca98d4-3d61e.png 960w,\n/static/multihead_attention_encoder-503fd3d322872609873e62cbb1ca98d4-71c2a.png 1138w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>To this attention output, we also add a residual connection as well as perform a layer normalization step:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/residual_layer_to_multihead_attention-8249f2237caed6af900dabf68ef86f39-14ffb.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 63.1304347826087%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Residual connection and layer normalization to multihead attention"\n        title=""\n        src="/static/residual_layer_to_multihead_attention-8249f2237caed6af900dabf68ef86f39-3d61e.png"\n        srcset="/static/residual_layer_to_multihead_attention-8249f2237caed6af900dabf68ef86f39-d182c.png 240w,\n/static/residual_layer_to_multihead_attention-8249f2237caed6af900dabf68ef86f39-5220f.png 480w,\n/static/residual_layer_to_multihead_attention-8249f2237caed6af900dabf68ef86f39-3d61e.png 960w,\n/static/residual_layer_to_multihead_attention-8249f2237caed6af900dabf68ef86f39-14ffb.png 1150w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Now, we feed this result into a feedforward layer also using a residual connection and layer normalization:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/feedforward_layer_and_normalization-dfdcfbd00009f7f99eca73ae29f2dfb7-4ec3a.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 91.13924050632912%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Feedforward layer and normalization to multihead attention in transformer model"\n        title=""\n        src="/static/feedforward_layer_and_normalization-dfdcfbd00009f7f99eca73ae29f2dfb7-3d61e.png"\n        srcset="/static/feedforward_layer_and_normalization-dfdcfbd00009f7f99eca73ae29f2dfb7-d182c.png 240w,\n/static/feedforward_layer_and_normalization-dfdcfbd00009f7f99eca73ae29f2dfb7-5220f.png 480w,\n/static/feedforward_layer_and_normalization-dfdcfbd00009f7f99eca73ae29f2dfb7-3d61e.png 960w,\n/static/feedforward_layer_and_normalization-dfdcfbd00009f7f99eca73ae29f2dfb7-4ec3a.png 1106w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>This is the result of our first layer encoder operation! This is fed as the input to another\nidentical layer. In total, the Transformer encoder uses six stacked layers:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/six_encoder_layers_transformer-c6bd6ede8fae9df6d646b5b5b25d7039-5430e.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 772px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 114.76683937823833%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Six stacked encoder layers in Transformer model"\n        title=""\n        src="/static/six_encoder_layers_transformer-c6bd6ede8fae9df6d646b5b5b25d7039-5430e.png"\n        srcset="/static/six_encoder_layers_transformer-c6bd6ede8fae9df6d646b5b5b25d7039-99c04.png 240w,\n/static/six_encoder_layers_transformer-c6bd6ede8fae9df6d646b5b5b25d7039-9bce9.png 480w,\n/static/six_encoder_layers_transformer-c6bd6ede8fae9df6d646b5b5b25d7039-5430e.png 772w"\n        sizes="(max-width: 772px) 100vw, 772px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>Now we can move on to the Transformer decoder. In practice, the decoder also uses six stacked layers\nthat perform a set of operations. These operations are largely identical to the encoder layer, except\nfor a few small differences:</p>\n<ul>\n<li>The first multi-head attention is a masked attention operation, where positions <em>after</em> the one being\nconsidered are not included in the attention computation</li>\n<li>Another multi-headed attention operation is included that has the decoder inputs attend over the output\nof the encoder stack. This operation takes inspiration from traditional recurrent sequence-to-sequence models.</li>\n</ul>\n<p>In practice this look as follows:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/decoder_layer_1-f3b40259790fe28ff916c856d677ab41-72d9e.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 57.41935483870968%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Transformer decoder first layer"\n        title=""\n        src="/static/decoder_layer_1-f3b40259790fe28ff916c856d677ab41-3d61e.png"\n        srcset="/static/decoder_layer_1-f3b40259790fe28ff916c856d677ab41-d182c.png 240w,\n/static/decoder_layer_1-f3b40259790fe28ff916c856d677ab41-5220f.png 480w,\n/static/decoder_layer_1-f3b40259790fe28ff916c856d677ab41-3d61e.png 960w,\n/static/decoder_layer_1-f3b40259790fe28ff916c856d677ab41-72d9e.png 1085w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>After performing these operations, we can predict the next token of our translated phrase:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/output_token-06e143fae69ea58572608d65a546255c-06aef.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 697px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 88.52223816355811%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Decoded output token transformer model"\n        title=""\n        src="/static/output_token-06e143fae69ea58572608d65a546255c-06aef.png"\n        srcset="/static/output_token-06e143fae69ea58572608d65a546255c-46026.png 240w,\n/static/output_token-06e143fae69ea58572608d65a546255c-d5fe8.png 480w,\n/static/output_token-06e143fae69ea58572608d65a546255c-06aef.png 697w"\n        sizes="(max-width: 697px) 100vw, 697px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>And that’s the Transformer!</p>\n<h2>How Transformers Are Built</h2>\n<p>While the Transformer architecture may seem conceptually simple, the devil is of course in the details. To that end, there are\nquite a few aspects that warrant some further description.  </p>\n<h3>Positional Encoding</h3>\n<p>The positional encoding added to the encoder and decoder inputs is the first question mark in the model. What’s up with that?</p>\n<p>Recall that the positional encoding is designed to help the model learn some notion of sequences and relative\npositioning of tokens. This is crucial for language-based tasks especially here because we are not making use of any\ntraditional recurrent units.</p>\n<p>In the Transformer architecture, the positional encoding is a vector described by the following equations:</p>\n<span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>P</mi><msub><mi>E</mi><mrow><mo>(</mo><mi>p</mi><mi>o</mi><mi>s</mi><mo separator="true">,</mo><mn>2</mn><mi>i</mi><mo>)</mo></mrow></msub><mo>=</mo><mi>sin</mi><mo>⁡</mo><mo>(</mo><mfrac><mrow><mi>p</mi><mi>o</mi><mi>s</mi></mrow><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><msup><mn>0</mn><mrow><mn>2</mn><mi>i</mi><mi mathvariant="normal">/</mi><msub><mi>d</mi><mrow><mi>m</mi><mi>o</mi><mi>d</mi><mi>e</mi><mi>l</mi></mrow></msub></mrow></msup></mrow></mfrac><mo>)</mo></mrow><annotation encoding="application/x-tex">PE_{(pos,2i)} = \\sin(\\frac{pos}{10000^{2i/d_{model}}})</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.10756em;"></span><span class="strut bottom" style="height:1.81156em;vertical-align:-0.704em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.34480000000000005em;"><span style="top:-2.5198em;margin-left:-0.05764em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathit mtight">p</span><span class="mord mathit mtight">o</span><span class="mord mathit mtight">s</span><span class="mpunct mtight">,</span><span class="mord mtight">2</span><span class="mord mathit mtight">i</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3551999999999999em;"></span></span></span></span></span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mrel">=</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mop">sin</span><span class="mopen">(</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.10756em;"><span style="top:-2.2960000000000003em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span><span class="mord">0</span><span class="mord">0</span><span class="mord">0</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.814em;"><span style="top:-2.989em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span><span class="mord mathit mtight">i</span><span class="mord mtight">/</span><span class="mord mtight"><span class="mord mathit mtight">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3487714285714287em;margin-left:0em;margin-right:0.07142857142857144em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathit mtight">m</span><span class="mord mathit mtight">o</span><span class="mord mathit mtight">d</span><span class="mord mathit mtight">e</span><span class="mord mathit mtight" style="margin-right:0.01968em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15122857142857138em;"></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span><span style="top:-3.15em;"><span class="pstrut" style="height:3em;"></span><span class="stretchy" style="height:0.2em;"><svg width=\'400em\' height=\'0.2em\' viewBox=\'0 0 400000 200\' preserveAspectRatio=\'xMinYMin slice\'><path d=\'M0 80H400000 v40H0z M0 80H400000 v40H0z\'/></svg></span></span><span style="top:-3.6770000000000005em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathit">p</span><span class="mord mathit">o</span><span class="mord mathit">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.704em;"></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose">)</span></span></span></span></span>\n<span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>P</mi><msub><mi>E</mi><mrow><mo>(</mo><mi>p</mi><mi>o</mi><mi>s</mi><mo separator="true">,</mo><mn>2</mn><mi>i</mi><mo>+</mo><mn>1</mn><mo>)</mo></mrow></msub><mo>=</mo><mi>cos</mi><mo>⁡</mo><mo>(</mo><mfrac><mrow><mi>p</mi><mi>o</mi><mi>s</mi></mrow><mrow><mn>1</mn><mn>0</mn><mn>0</mn><mn>0</mn><msup><mn>0</mn><mrow><mn>2</mn><mi>i</mi><mi mathvariant="normal">/</mi><msub><mi>d</mi><mrow><mi>m</mi><mi>o</mi><mi>d</mi><mi>e</mi><mi>l</mi></mrow></msub></mrow></msup></mrow></mfrac><mo>)</mo></mrow><annotation encoding="application/x-tex">PE_{(pos,2i+1)} = \\cos(\\frac{pos}{10000^{2i/d_{model}}})</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.10756em;"></span><span class="strut bottom" style="height:1.81156em;vertical-align:-0.704em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.34480000000000005em;"><span style="top:-2.5198em;margin-left:-0.05764em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mopen mtight">(</span><span class="mord mathit mtight">p</span><span class="mord mathit mtight">o</span><span class="mord mathit mtight">s</span><span class="mpunct mtight">,</span><span class="mord mtight">2</span><span class="mord mathit mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3551999999999999em;"></span></span></span></span></span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mrel">=</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mop">cos</span><span class="mopen">(</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.10756em;"><span style="top:-2.2960000000000003em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span><span class="mord">0</span><span class="mord">0</span><span class="mord">0</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.814em;"><span style="top:-2.989em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">2</span><span class="mord mathit mtight">i</span><span class="mord mtight">/</span><span class="mord mtight"><span class="mord mathit mtight">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3487714285714287em;margin-left:0em;margin-right:0.07142857142857144em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathit mtight">m</span><span class="mord mathit mtight">o</span><span class="mord mathit mtight">d</span><span class="mord mathit mtight">e</span><span class="mord mathit mtight" style="margin-right:0.01968em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15122857142857138em;"></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span><span style="top:-3.15em;"><span class="pstrut" style="height:3em;"></span><span class="stretchy" style="height:0.2em;"><svg width=\'400em\' height=\'0.2em\' viewBox=\'0 0 400000 200\' preserveAspectRatio=\'xMinYMin slice\'><path d=\'M0 80H400000 v40H0z M0 80H400000 v40H0z\'/></svg></span></span><span style="top:-3.6770000000000005em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathit">p</span><span class="mord mathit">o</span><span class="mord mathit">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.704em;"></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose">)</span></span></span></span></span>\n<p>Here the <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.65952em;"></span><span class="strut bottom" style="height:0.65952em;vertical-align:0em;"></span><span class="base"><span class="mord mathit">i</span></span></span></span> denotes the vector index we are looking at, <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>p</mi><mi>o</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">pos</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.625em;vertical-align:-0.19444em;"></span><span class="base"><span class="mord mathit">p</span><span class="mord mathit">o</span><span class="mord mathit">s</span></span></span></span> denotes the token, and <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>d</mi><mrow><mi>m</mi><mi>o</mi><mi>d</mi><mi>e</mi><mi>l</mi></mrow></msub></mrow><annotation encoding="application/x-tex">d_{model}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.84444em;vertical-align:-0.15em;"></span><span class="base"><span class="mord"><span class="mord mathit">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.33610799999999996em;"><span style="top:-2.5500000000000003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathit mtight">m</span><span class="mord mathit mtight">o</span><span class="mord mathit mtight">d</span><span class="mord mathit mtight">e</span><span class="mord mathit mtight" style="margin-right:0.01968em;">l</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"></span></span></span></span></span></span></span></span> denotes a fixed\nconstant representing the dimension of the input embeddings. Ok let’s break it down further.</p>\n<p>What this vector is basically saying is that for a given fixed vector index, as we vary the <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>p</mi><mi>o</mi><mi>s</mi></mrow><annotation encoding="application/x-tex">pos</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.625em;vertical-align:-0.19444em;"></span><span class="base"><span class="mord mathit">p</span><span class="mord mathit">o</span><span class="mord mathit">s</span></span></span></span> (corresponding to\ntokens at different positions), we form a sinusoid:</p>\n<p>\n  <a\n    class="gatsby-resp-image-link"\n    href="/static/sinusoid_positional_encoding-f7fd3bd7e871f5a2290f32a75729391c-58203.png"\n    style="display: block"\n    target="_blank"\n    rel="noopener"\n  >\n  \n  <span\n    class="gatsby-resp-image-wrapper"\n    style="position: relative; display: block; ; max-width: 960px; margin-left: auto; margin-right: auto;"\n  >\n    <span\n      class="gatsby-resp-image-background-image"\n      style="padding-bottom: 50%; position: relative; bottom: 0; left: 0; background-image: url(\'data:image/png;base64,\'); background-size: cover; display: block;"\n    >\n      <img\n        class="gatsby-resp-image-image"\n        style="width: 100%; height: 100%; margin: 0; vertical-align: middle; position: absolute; top: 0; left: 0; box-shadow: inset 0px 0px 0px 400px white;"\n        alt="Sinusoid positional encoding"\n        title=""\n        src="/static/sinusoid_positional_encoding-f7fd3bd7e871f5a2290f32a75729391c-3d61e.png"\n        srcset="/static/sinusoid_positional_encoding-f7fd3bd7e871f5a2290f32a75729391c-d182c.png 240w,\n/static/sinusoid_positional_encoding-f7fd3bd7e871f5a2290f32a75729391c-5220f.png 480w,\n/static/sinusoid_positional_encoding-f7fd3bd7e871f5a2290f32a75729391c-3d61e.png 960w,\n/static/sinusoid_positional_encoding-f7fd3bd7e871f5a2290f32a75729391c-58203.png 1280w"\n        sizes="(max-width: 960px) 100vw, 960px"\n      />\n    </span>\n  </span>\n  \n  </a>\n    </p>\n<p>This particular form for the positional encoding was chosen because the value for the encoding at a given position\n<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>P</mi><msub><mi>E</mi><mrow><mi>p</mi><mi>o</mi><mi>s</mi><mo>+</mo><mi>k</mi></mrow></msub></mrow><annotation encoding="application/x-tex">PE_{pos+k}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.969438em;vertical-align:-0.286108em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361079999999999em;"><span style="top:-2.5500000000000003em;margin-left:-0.05764em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathit mtight">p</span><span class="mord mathit mtight">o</span><span class="mord mathit mtight">s</span><span class="mbin mtight">+</span><span class="mord mathit mtight" style="margin-right:0.03148em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.286108em;"></span></span></span></span></span></span></span></span> can be represented as a linear function of values for the encoding at earlier positions <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>P</mi><msub><mi>E</mi><mrow><mi>p</mi><mi>o</mi><mi>s</mi></mrow></msub></mrow><annotation encoding="application/x-tex">PE_{pos}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.969438em;vertical-align:-0.286108em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.13889em;">P</span><span class="mord"><span class="mord mathit" style="margin-right:0.05764em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.15139200000000003em;"><span style="top:-2.5500000000000003em;margin-left:-0.05764em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathit mtight">p</span><span class="mord mathit mtight">o</span><span class="mord mathit mtight">s</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.286108em;"></span></span></span></span></span></span></span></span>. This\nfollows from trigonometric identities and is equivalent to saying that a given token can learn to attend to earlier tokens\nin a sequence. This is an <strong>essential</strong> property for the Transformer.</p>\n<h3>Multi-head Attention</h3>\n<p>The multi-head attention operation is one of the main contributions of this model. So let’s dive into how it works.</p>\n<p>At a high-level, an attention operation is designed to help a certain token in a natural language architecture focus on certain aspects of another part of the model,\nusually another collection of tokens. Keep in mind that attention operations can be used in other problem domains like computer vision,\neven though here we are focusing on natural language.</p>\n<p>More formally, an attention takes a <em>query</em>, computes some weights with respect to a set of <em>keys</em>, and uses those weights\nto form a weighted combination of a collection of <em>values</em>. In mathematical terms, the Transformer attention can be\ndescribed as:</p>\n<span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mtext>Attention</mtext><mo>(</mo><mi>Q</mi><mo separator="true">,</mo><mi>K</mi><mo separator="true">,</mo><mi>V</mi><mo>)</mo><mo>=</mo><mtext>softmax</mtext><mo>(</mo><mfrac><mrow><mi>Q</mi><msup><mi>K</mi><mi>T</mi></msup></mrow><mrow><msqrt><mrow><msub><mi>d</mi><mi>k</mi></msub></mrow></msqrt></mrow></mfrac><mo>)</mo><mi>V</mi></mrow><annotation encoding="application/x-tex">    \\textrm{Attention}(Q, K, V) = \\textrm{softmax}(\\frac{QK^T}{\\sqrt{d_k}})V</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:1.518331em;"></span><span class="strut bottom" style="height:2.448331em;vertical-align:-0.93em;"></span><span class="base"><span class="mord text"><span class="mord textrm">Attention</span></span><span class="mopen">(</span><span class="mord mathit">Q</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="mclose">)</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mrel">=</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mord text"><span class="mord textrm">softmax</span></span><span class="mopen">(</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.518331em;"><span style="top:-2.25278em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord sqrt"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.85722em;"><span class="svg-align" style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord" style="padding-left:0.833em;"><span class="mord"><span class="mord mathit">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.33610799999999996em;"><span style="top:-2.5500000000000003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight" style="margin-right:0.03148em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"></span></span></span></span></span></span></span><span style="top:-2.81722em;"><span class="pstrut" style="height:3em;"></span><span class="hide-tail" style="min-width:0.853em;height:1.08em;"><svg width=\'400em\' height=\'1.08em\' viewBox=\'0 0 400000 1080\' preserveAspectRatio=\'xMinYMin slice\'><path d=\'M95,702c-2.7,0,-7.17,-2.7,-13.5,-8c-5.8,-5.3,-9.5,\n-10,-9.5,-14c0,-2,0.3,-3.3,1,-4c1.3,-2.7,23.83,-20.7,67.5,-54c44.2,-33.3,65.8,\n-50.3,66.5,-51c1.3,-1.3,3,-2,5,-2c4.7,0,8.7,3.3,12,10s173,378,173,378c0.7,0,\n35.3,-71,104,-213c68.7,-142,137.5,-285,206.5,-429c69,-144,104.5,-217.7,106.5,\n-221c5.3,-9.3,12,-14,20,-14H400000v40H845.2724s-225.272,467,-225.272,467\ns-235,486,-235,486c-2.7,4.7,-9,7,-19,7c-6,0,-10,-1,-12,-3s-194,-422,-194,-422\ns-65,47,-65,47z M834 80H400000v40H845z\'/></svg></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.18278000000000005em;"></span></span></span></span></span></span><span style="top:-3.15em;"><span class="pstrut" style="height:3em;"></span><span class="stretchy" style="height:0.2em;"><svg width=\'400em\' height=\'0.2em\' viewBox=\'0 0 400000 200\' preserveAspectRatio=\'xMinYMin slice\'><path d=\'M0 80H400000 v40H0z M0 80H400000 v40H0z\'/></svg></span></span><span style="top:-3.6770000000000005em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathit">Q</span><span class="mord"><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413309999999999em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight" style="margin-right:0.13889em;">T</span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.93em;"></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mclose">)</span><span class="mord mathit" style="margin-right:0.22222em;">V</span></span></span></span></span>\n<p>where <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base"><span class="mord mathit">Q</span></span></span></span>, <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>K</mi></mrow><annotation encoding="application/x-tex">K</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.07153em;">K</span></span></span></span>, and <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>V</mi></mrow><annotation encoding="application/x-tex">V</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.22222em;">V</span></span></span></span> are the query, key, and value matrices respectively and <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mi>d</mi><mi>k</mi></msub></mrow><annotation encoding="application/x-tex">d_k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.84444em;vertical-align:-0.15em;"></span><span class="base"><span class="mord"><span class="mord mathit">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.33610799999999996em;"><span style="top:-2.5500000000000003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight" style="margin-right:0.03148em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"></span></span></span></span></span></span></span></span> is a fixed scaling constant. </p>\n<p>In the case of the encoder self-attention, the keys, values, and queries are all the same value, namely the output from\nthe previous layer of encoding.</p>\n<p>In the case of the masked decoder self-attention, the same is true except that a mask is applied so that a position of decoding\ncan only attend to previous positions. </p>\n<p>In the case of the encoder-decoder attention, the keys and values are the output of the encoder layer stack and the\nqueries are the output of the previous decoder layer. </p>\n<p>The multi-head attention operation basically means that instead of applying an attention operation once, we will do it several\ntimes (8 in the case of the Transformer model). Mathematically, this looks like:</p>\n<span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mtext>MultiHead</mtext><mo>(</mo><mi>Q</mi><mo separator="true">,</mo><mi>K</mi><mo separator="true">,</mo><mi>V</mi><mo>)</mo><mo>=</mo><mtext>Concatenate</mtext><mo>(</mo><msub><mtext>head</mtext><mn>1</mn></msub><mo separator="true">,</mo><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mi mathvariant="normal">.</mi><mo separator="true">,</mo><msub><mtext>head</mtext><mi>h</mi></msub><mo>)</mo><msup><mi>W</mi><mi>O</mi></msup></mrow><annotation encoding="application/x-tex">\\textrm{MultiHead}(Q, K, V) = \\textrm{Concatenate}(\\textrm{head}_1, ..., \\textrm{head}_h)W^O </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8913309999999999em;"></span><span class="strut bottom" style="height:1.1413309999999999em;vertical-align:-0.25em;"></span><span class="base"><span class="mord text"><span class="mord textrm">MultiHead</span></span><span class="mopen">(</span><span class="mord mathit">Q</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="mclose">)</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mrel">=</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mord text"><span class="mord textrm">Concatenate</span></span><span class="mopen">(</span><span class="mord"><span class="mord text"><span class="mord textrm">head</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.30110799999999993em;"><span style="top:-2.5500000000000003em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"></span></span></span></span></span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord">.</span><span class="mord">.</span><span class="mord">.</span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord"><span class="mord text"><span class="mord textrm">head</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.33610799999999996em;"><span style="top:-2.5500000000000003em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">W</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8913309999999999em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight" style="margin-right:0.02778em;">O</span></span></span></span></span></span></span></span></span></span></span></span>\n<span class="katex-display"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><msub><mtext>head</mtext><mi>i</mi></msub><mo>=</mo><mtext>Attention</mtext><mo>(</mo><mi>Q</mi><msubsup><mi>W</mi><mi>i</mi><mi>Q</mi></msubsup><mo separator="true">,</mo><mi>K</mi><msubsup><mi>W</mi><mi>i</mi><mi>K</mi></msubsup><mo separator="true">,</mo><mi>V</mi><msubsup><mi>W</mi><mi>i</mi><mi>V</mi></msubsup><mo>)</mo></mrow><annotation encoding="application/x-tex">\\textrm{head}_i = \\textrm{Attention}(QW_i^Q, KW_i^K, VW_i^V)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.9592389999999998em;"></span><span class="strut bottom" style="height:1.236103em;vertical-align:-0.276864em;"></span><span class="base"><span class="mord"><span class="mord text"><span class="mord textrm">head</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.31166399999999994em;"><span style="top:-2.5500000000000003em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"></span></span></span></span></span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mrel">=</span><span class="mord rule" style="margin-right:0.2777777777777778em;"></span><span class="mord text"><span class="mord textrm">Attention</span></span><span class="mopen">(</span><span class="mord mathit">Q</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9592389999999998em;"><span style="top:-2.4231360000000004em;margin-left:-0.13889em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight">i</span></span></span><span style="top:-3.180908em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight">Q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.276864em;"></span></span></span></span></span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord mathit" style="margin-right:0.07153em;">K</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913309999999999em;"><span style="top:-2.4530000000000003em;margin-left:-0.13889em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight" style="margin-right:0.07153em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"></span></span></span></span></span><span class="mpunct">,</span><span class="mord rule" style="margin-right:0.16666666666666666em;"></span><span class="mord mathit" style="margin-right:0.22222em;">V</span><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913309999999999em;"><span style="top:-2.4530000000000003em;margin-left:-0.13889em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight">i</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathit mtight" style="margin-right:0.22222em;">V</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"></span></span></span></span></span><span class="mclose">)</span></span></span></span></span>\n<p>where <span class="katex"><span class="katex-mathml"><math><semantics><mrow><msubsup><mi>W</mi><mo>∗</mo><mo>∗</mo></msubsup></mrow><annotation encoding="application/x-tex">W_{*}^{*}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.688696em;"></span><span class="strut bottom" style="height:0.935696em;vertical-align:-0.247em;"></span><span class="base"><span class="mord"><span class="mord mathit" style="margin-right:0.13889em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.688696em;"><span style="top:-2.4530000000000003em;margin-left:-0.13889em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∗</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∗</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"></span></span></span></span></span></span></span></span> are appropriately-dimensioned weight matrices. The beauty of the multi-head attention is that\nthe operation is easily parallelizable, which leads to reduced runtime. </p>\n<h2>Experiments</h2>\n<p>In spite of circumventing the traditional recurrent architectures, the Transformer is amazing because it is still able to\noutperform its recurrent counterparts. On the English-to-German and English-to-French WMT translation tasks, the Transformer achieves\nstate-of-the-art BLEU scores (41.8 on EN-FR and 28.4 on EN-DE). </p>\n<p>Not only that, but because of its highly parallelizable nature, the Transformer is able to do this at a significantly-reduced\nnumbers of FLOPs (floating-point operations) for training! So the Transformer is <em>better</em> and <em>faster</em>!</p>\n<h2>Analysis</h2>\n<p>This whole notion of self-attention is an essential one in the Transformer architecture. It\nWhy is self-attention a desirable thing to use as the backbone of a model? </p>\n<p>One of the big advantages of self-attention is how efficient of an operation it is. A complexity comparison of\nself-attention to other conventional network operations illustrates this:</p>\n<table>\n<thead>\n<tr>\n<th>Layer Type</th>\n<th align="center">Layer Complexity</th>\n<th align="right">Sequential Operations</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Self-Attention</td>\n<td align="center"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><msup><mi>n</mi><mn>2</mn></msup><mo>⋅</mo><mi>d</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">O(n^2\\cdot d)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathit">n</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141079999999999em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mbin">⋅</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mord mathit">d</span><span class="mclose">)</span></span></span></span></td>\n<td align="right"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">O(1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord">1</span><span class="mclose">)</span></span></span></span></td>\n</tr>\n<tr>\n<td>Recurrent</td>\n<td align="center"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mi>n</mi><mo>⋅</mo><msup><mi>d</mi><mn>2</mn></msup><mo>)</mo></mrow><annotation encoding="application/x-tex">O(n\\cdot d^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathit">n</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mbin">⋅</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mord"><span class="mord mathit">d</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141079999999999em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></td>\n<td align="right"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mi>n</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">O(n)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathit">n</span><span class="mclose">)</span></span></span></span></td>\n</tr>\n<tr>\n<td>Convolutional</td>\n<td align="center"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mi>k</mi><mo>⋅</mo><mi>n</mi><mo>⋅</mo><msup><mi>d</mi><mn>2</mn></msup><mo>)</mo></mrow><annotation encoding="application/x-tex">O(k\\cdot n \\cdot d^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathit" style="margin-right:0.03148em;">k</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mbin">⋅</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mord mathit">n</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mbin">⋅</span><span class="mord rule" style="margin-right:0.2222222222222222em;"></span><span class="mord"><span class="mord mathit">d</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141079999999999em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span></td>\n<td align="right"><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">O(1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord">1</span><span class="mclose">)</span></span></span></span></td>\n</tr>\n</tbody>\n</table>\n<p>Above, layer complexity denotes the number of computations performed per layer. In this case, self-attention is more\nefficient than recurrence as long as the sequence length <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base"><span class="mord mathit">n</span></span></span></span> is less than the input embedding dimension <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>d</mi></mrow><annotation encoding="application/x-tex">d</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.69444em;"></span><span class="strut bottom" style="height:0.69444em;vertical-align:0em;"></span><span class="base"><span class="mord mathit">d</span></span></span></span>, which is\ntypically true.</p>\n<p>The self-attention operation also connects all positions through a constant time number of computations, compared\nto recurrence which requires linear-time computations. </p>\n<h2>Final Thoughts</h2>\n<p>The Transformer is a real rebel in the natural language deep learning scene because of how it eschews conventional network constructs\nwhile still outperforming existing systems. It has challenged a lot of folk wisdom about the necessity of recurrence\nin natural language models. Since being released, the Transformer has been extended and used in new architectures, most recently <a href="https://arxiv.org/abs/1810.04805">BERT</a>.</p>\n<p>Is attention <em>really</em> all you need? Future work will answer that question!</p>',
fields:{tagSlugs:["/tags/a-i/","/tags/natural-language-processing/","/tags/deep-learning/"]},frontmatter:{title:"Transformers: Attention in Disguise",tags:["A.I.","Natural Language Processing","Deep Learning"],date:"2018-10-22T23:46:37.121",description:"We discuss the Transformer, a purely attention-based architecture that is more performant, more efficient, and more parallelizable than recurrent network-based models."}}},pathContext:{slug:"/posts/transformers-attention-in-disguise/"}}}});
